async function bumpStat(field) {
  try {
    let counts = {};
    try {
      const res = await window.storage.get(ANALYTICS_KEY, true);
      counts = res ? JSON.parse(res.value) : {};
    } catch { counts = {}; }
    const today = todayISO();
    counts.totals = counts.totals || {};
    counts.totals[field] = (counts.totals[field] || 0) + 1;
    counts.daily = counts.daily || {};
    counts.daily[today] = counts.daily[today] || {};
    counts.daily[today][field] = (counts.daily[today][field] || 0) + 1;
    await window.storage.set(ANALYTICS_KEY, JSON.stringify(counts), true);
  } catch {
    /* analytics are best-effort; never block the user's flow */
  }
}

async function loadContent() {
  try {
    const res = await window.storage.get(CONTENT_KEY, true);
    const saved = res ? JSON.parse(res.value) : {};
    return { ...DEFAULT_CONTENT, ...saved };
  } catch {
    return DEFAULT_CONTENT;
  }
}
