function ChipGroup({ options, value, onChange, multi }) {
  const isActive = (opt) => (multi ? (value || []).includes(opt) : value === opt);
  const toggle = (opt) => {
    if (multi) {
      const set = new Set(value || []);
      set.has(opt) ? set.delete(opt) : set.add(opt);
      onChange([...set]);
    } else {
      onChange(value === opt ? "" : opt);
    }
  };
  return (
    <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
      {options.map(opt => (
        <button
          type="button"
          key={opt}
          onClick={() => toggle(opt)}
          style={{
            padding: "9px 15px",
            borderRadius: 999,
            border: `1.5px solid ${isActive(opt) ? COLORS.pink600 : COLORS.line}`,
            background: isActive(opt) ? COLORS.pink600 : "#FFFCFD",
            color: isActive(opt) ? "#fff" : COLORS.plum700,
            fontSize: 13.5, fontWeight: 600, cursor: "pointer",
            fontFamily: "'Plus Jakarta Sans', sans-serif",
            transition: "all 0.15s ease",
          }}
        >{opt}</button>
      ))}
    </div>
  );
}

