/* ----------------------------------------------------------------------
   SIGNATURE ELEMENT: CYCLE RING
------------------------------------------------------------------------ */
function CycleRing({ currentDay, cycleLen, periodLen, size = 232 }) {
  const L = Math.max(cycleLen, currentDay, 20);
  const P = Math.min(periodLen, L);
  const ovulationDay = clamp(L - 14, P + 1, L - 1);
  const fertileStart = clamp(ovulationDay - 3, P + 1, L);
  const fertileEnd = clamp(ovulationDay + 1, P + 1, L);

  const pct = (d) => clamp((d / L) * 100, 0, 100);

  const segs = [
    { from: 0, to: P, color: COLORS.pink600 },              // menstrual
    { from: P, to: fertileStart, color: COLORS.pink200 },     // follicular
    { from: fertileStart, to: fertileEnd, color: COLORS.gold }, // fertile window
    { from: fertileEnd, to: L, color: "#EAD6DE" },             // luteal
  ];

  let gradientParts = [];
  segs.forEach(s => {
    gradientParts.push(`${s.color} ${pct(s.from)}% ${pct(s.to)}%`);
  });
  const gradient = `conic-gradient(from -90deg, ${gradientParts.join(", ")})`;
  const markerAngle = (clamp(currentDay, 1, L) / L) * 360 - 90;
  const markerRad = (size / 2) - 9;

  return (
    <div style={{ position: "relative", width: size, height: size, margin: "0 auto" }}>
      <div style={{ width: size, height: size, borderRadius: "50%", background: gradient }} />
      <div style={{
        position: "absolute", inset: 16, borderRadius: "50%", background: COLORS.card,
        display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
        boxShadow: "inset 0 0 0 1px rgba(196,80,120,0.06)",
      }}>
        <div style={{ fontFamily: "'Fraunces', serif", fontSize: 46, fontWeight: 600, color: COLORS.plum900, lineHeight: 1 }}>
          {currentDay}
        </div>
        <div style={{ fontSize: 11.5, fontWeight: 700, color: COLORS.pink600, letterSpacing: "0.06em", textTransform: "uppercase", marginTop: 6 }}>
          Day of Cycle
        </div>
      </div>
      <div style={{
        position: "absolute", top: "50%", left: "50%", width: 14, height: 14, borderRadius: "50%",
        background: "#fff", border: `3px solid ${COLORS.pink700}`, boxShadow: "0 2px 6px rgba(0,0,0,0.2)",
        transform: `rotate(${markerAngle}deg) translate(${markerRad}px) rotate(${-markerAngle}deg) translate(-7px,-7px)`,
      }} />
    </div>
  );
}

/* ----------------------------------------------------------------------
   MINI BAR CHART (cycle length history) — no external chart lib needed
------------------------------------------------------------------------ */
function CycleLengthChart({ lengths }) {
  if (!lengths.length) {
    return <div style={{ fontSize: 13.5, color: COLORS.plum500, padding: "10px 0" }}>Log a second period to see your cycle-length trend here.</div>;
  }
  const max = Math.max(...lengths, 32);
  const min = Math.min(...lengths, 24);
  const range = Math.max(max - min, 6);
  return (
    <div style={{ display: "flex", alignItems: "flex-end", gap: 10, height: 120, padding: "8px 2px 0" }}>
      {lengths.map((len, i) => {
        const h = 24 + ((len - min) / range) * 78;
        return (
          <div key={i} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6, flex: 1 }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: COLORS.plum700 }}>{len}</div>
            <div style={{
              width: "100%", maxWidth: 26, height: h, borderRadius: 8,
              background: i === lengths.length - 1
                ? `linear-gradient(180deg, ${COLORS.pink500}, ${COLORS.pink700})`
                : COLORS.pink200,
            }} />
            <div style={{ fontSize: 10, color: COLORS.plum500 }}>#{i + 2}</div>
          </div>
        );
      })}
    </div>
  );
}

/* ----------------------------------------------------------------------
   CALENDAR
------------------------------------------------------------------------ */
function isBetween(iso, startIso, endIso) {
  return iso >= startIso && iso <= endIso;
}

function MonthCalendar({ cycles, prediction }) {
  const [cursor, setCursor] = useState(() => { const d = new Date(); d.setDate(1); return d; });
  const year = cursor.getFullYear(), month = cursor.getMonth();
  const firstDow = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const cells = [];
  for (let i = 0; i < firstDow; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);

  const dayType = (d) => {
    const iso = toISO(new Date(year, month, d));
    for (const c of cycles) {
      const end = c.end || (c.periodDuration ? addDays(c.start, Number(c.periodDuration) - 1) : c.start);
      if (isBetween(iso, c.start, end)) return "period";
    }
    if (prediction && isBetween(iso, prediction.windowStart, prediction.windowEnd)) {
      return iso === prediction.nextStart ? "predicted-main" : "predicted";
    }
    return null;
  };

  const isToday = (d) => toISO(new Date(year, month, d)) === todayISO();

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 14 }}>
        <button onClick={() => setCursor(new Date(year, month - 1, 1))} style={navBtnStyle}><ChevronLeft size={17} color={COLORS.plum700} /></button>
        <div style={{ fontFamily: "'Fraunces', serif", fontWeight: 600, fontSize: 17, color: COLORS.plum900 }}>
          {cursor.toLocaleDateString("en-US", { month: "long", year: "numeric" })}
        </div>
        <button onClick={() => setCursor(new Date(year, month + 1, 1))} style={navBtnStyle}><ChevronRight size={17} color={COLORS.plum700} /></button>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7,1fr)", gap: 4, marginBottom: 6 }}>
        {["S", "M", "T", "W", "T", "F", "S"].map((d, i) => (
          <div key={i} style={{ textAlign: "center", fontSize: 11, fontWeight: 700, color: COLORS.plum500 }}>{d}</div>
        ))}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7,1fr)", gap: 4 }}>
        {cells.map((d, i) => {
          if (!d) return <div key={i} />;
          const type = dayType(d);
          let bg = "transparent", color = COLORS.plum700, border = "none", fontWeight = 500;
          if (type === "period") { bg = COLORS.pink600; color = "#fff"; fontWeight = 700; }
          else if (type === "predicted-main") { bg = COLORS.gold; color = "#fff"; fontWeight = 700; }
          else if (type === "predicted") { bg = "#FBEBD0"; color = COLORS.plum900; fontWeight = 600; }
          if (isToday(d)) border = `2px solid ${COLORS.pink700}`;
          return (
            <div key={i} style={{
              aspectRatio: "1", display: "flex", alignItems: "center", justifyContent: "center",
              borderRadius: 10, background: bg, color, fontSize: 12.5, fontWeight, border,
              boxSizing: "border-box",
            }}>{d}</div>
          );
        })}
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "10px 16px", marginTop: 16 }}>
        <Legend swatch={COLORS.pink600} label="Period" />
        <Legend swatch={COLORS.gold} label="Predicted" />
        <Legend swatch="#FBEBD0" label="Likely window" />
      </div>
    </div>
  );
}
