function SymptomTracker({ onBack, onSave }) {
  const [selected, setSelected] = useState({});
  const toggle = (key) => {
    setSelected(s => {
      const copy = { ...s };
      if (key in copy) delete copy[key]; else copy[key] = 5;
      return copy;
    });
  };
  const setSeverity = (key, val) => setSelected(s => ({ ...s, [key]: val }));

  return (
    <div style={{ maxWidth: 480, margin: "0 auto" }}>
      <TopBar title="Track Symptoms 🤕" onBack={onBack} />
      <div style={{ padding: "16px 20px", display: "flex", flexDirection: "column", gap: 14 }}>
        {SYMPTOM_LIST.map(s => (
          <Card key={s.key} style={{ padding: "14px 18px" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", cursor: "pointer" }} onClick={() => toggle(s.key)}>
              <div style={{ display: "flex", alignItems: "center", gap: 10, fontWeight: 700, color: COLORS.plum900, fontSize: 14.5 }}>
                <span>{s.emoji}</span>{s.label}
              </div>
              <div style={{
                width: 24, height: 24, borderRadius: 8, border: `2px solid ${s.key in selected ? COLORS.pink600 : COLORS.line}`,
                background: s.key in selected ? COLORS.pink600 : "transparent",
                display: "flex", alignItems: "center", justifyContent: "center",
              }}>{s.key in selected && <Check size={15} color="#fff" />}</div>
            </div>
            {s.key in selected && (
              <div style={{ marginTop: 12 }}>
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11.5, color: COLORS.plum500, marginBottom: 4 }}>
                  <span>Severity</span><span style={{ fontWeight: 700, color: COLORS.pink700 }}>{selected[s.key]}/10</span>
                </div>
                <input type="range" min="0" max="10" value={selected[s.key]} onChange={e => setSeverity(s.key, Number(e.target.value))}
                  style={{ width: "100%", accentColor: COLORS.pink600 }} />
              </div>
            )}
          </Card>
        ))}
        <PrimaryButton onClick={() => onSave(selected)}>Save Symptoms <Check size={17} /></PrimaryButton>
      </div>
    </div>
  );
}

