/* ----------------------------------------------------------------------
   HISTORY PAGE
------------------------------------------------------------------------ */
function HistoryPage({ cycles, onBack, onEdit }) {
  const { sorted } = cycleLengthsFromCycles(cycles);
  const reversed = [...sorted].reverse();

  return (
    <div style={{ maxWidth: 480, margin: "0 auto" }}>
      <TopBar title="Cycle History 📊" onBack={onBack} />
      <div style={{ padding: "16px 20px", display: "flex", flexDirection: "column", gap: 14 }}>
        {reversed.length === 0 && (
          <Card><div style={{ fontSize: 14, color: COLORS.plum500 }}>No cycles recorded yet.</div></Card>
        )}
        {reversed.map((c, idx) => {
          const num = sorted.length - idx;
          const prev = sorted[sorted.findIndex(x => x.id === c.id) - 1];
          const cycleLen = prev ? diffDays(prev.start, c.start) : null;
          return (
            <Card key={c.id}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                <div style={{ fontFamily: "'Fraunces', serif", fontWeight: 600, fontSize: 17, color: COLORS.plum900 }}>Cycle #{num}</div>
                <button onClick={() => onEdit(c)} style={{
                  fontSize: 12.5, fontWeight: 700, color: COLORS.pink600, background: COLORS.cardAlt,
                  border: "none", borderRadius: 10, padding: "6px 12px", cursor: "pointer",
                }}>Edit</button>
              </div>
              <div style={{ marginTop: 8, fontSize: 13.5, color: COLORS.plum700, display: "flex", flexDirection: "column", gap: 4 }}>
                <div>🩸 {fmtShort(c.start)}{c.end ? ` – ${fmtShort(c.end)}` : ""}</div>
                {cycleLen && <div>🔄 Cycle length: {cycleLen} days</div>}
                {c.periodDuration && <div>🩸 Period duration: {c.periodDuration} days</div>}
                {c.regularity && <div>📋 Regularity: {c.regularity}</div>}
                {c.flowByDay && Object.keys(c.flowByDay).length > 0 && (
                  <div>💧 Flow: {Object.values(c.flowByDay).filter(Boolean).join(", ") || "—"}</div>
                )}
              </div>
            </Card>
          );
        })}
      </div>
    </div>
  );
}

