/* ----------------------------------------------------------------------
   PERSONALIZED SUGGESTIONS ENGINE
   Draws on every piece of data the user has provided — onboarding
   profile, today's lifestyle log, and logged symptoms — to surface
   plain-language, non-diagnostic wellness suggestions.
------------------------------------------------------------------------ */
const lastOf = (arr) => (arr && arr.length ? arr[arr.length - 1] : null);

function generateSuggestions(data) {
  const profile = data.profile || {};
  const latestLife = lastOf(data.lifestyleLogs);
  const latestSymptom = lastOf(data.symptomLogs);

  const water = parseFloat(latestLife?.water ?? profile.water);
  const sleep = parseFloat(latestLife?.sleep ?? profile.sleep);
  const stress = latestLife?.stress || profile.stress;
  const activity = latestLife?.exercise || profile.activity;
  const diet = latestLife?.diet || profile.diet;

  const tips = [], notes = [], goods = [];

  if (!isNaN(water)) {
    if (water < 2) tips.push({ emoji: "💧", text: `You're logging ${water}L of water a day — try working up to 2–3L. Better hydration can ease bloating and cramps.` });
    else goods.push({ emoji: "💧", text: `Your water intake (${water}L/day) looks solid — keep it up.` });
  }
  if (!isNaN(sleep)) {
    if (sleep < 7) tips.push({ emoji: "😴", text: `You're averaging ${sleep} hrs of sleep — aim for 7–8 hrs. Consistent sleep helps keep hormones and cycle timing steady.` });
    else goods.push({ emoji: "😴", text: `${sleep} hrs of sleep is a great range for hormonal balance.` });
  }
  if (stress === "High") tips.push({ emoji: "😰", text: "Your stress level is high — short walks, deep breathing, or journaling can help. Ongoing stress can delay ovulation and shift your cycle." });
  else if (stress === "Low") goods.push({ emoji: "😊", text: "Low stress levels support a more predictable cycle." });

  if (activity === "Low" || activity === "None") tips.push({ emoji: "🏃", text: "Try adding light movement like walking or stretching — it can ease period-related fatigue and lift your mood." });
  else if (activity === "High" || activity === "Intense") notes.push({ emoji: "🏃", text: "Intense training can sometimes affect cycle regularity — worth watching if your cycle feels off." });

  if (latestLife?.illness === "Yes") notes.push({ emoji: "🤒", text: "You reported feeling unwell recently — illness can temporarily shift your cycle timing." });
  if (latestLife?.travel === "Yes") notes.push({ emoji: "✈️", text: "Recent travel or a time-zone change can nudge your cycle — don't worry if this one looks a little different." });
  if (latestLife?.contraception === "Yes") notes.push({ emoji: "💊", text: "Hormonal contraception regulates your cycle directly, so natural predictions may be less precise for you." });
  if (latestLife?.weightChange === "Yes") notes.push({ emoji: "⚖️", text: "A recent significant weight change can affect cycle regularity — keep logging to track the pattern." });
  if (latestLife?.lifestyleChange === "Yes") notes.push({ emoji: "🔄", text: "Big routine changes can temporarily affect your cycle — this should settle as things stabilize." });

  if (latestSymptom) {
    const high = (latestSymptom.symptoms || []).filter(s => s.severity >= 7);
    const symptomTips = {
      cramps: "A warm compress, gentle stretching, and staying hydrated can help ease cramps.",
      headache: "Resting in a dim, quiet space and staying hydrated often helps hormonal headaches.",
      fatigue: (diet === "Vegetarian" || diet === "Vegan")
        ? "On a plant-based diet, keep an eye on iron-rich foods like lentils, spinach, and tofu — this can help with period fatigue."
        : "Prioritize rest and easy, iron-rich meals to help with fatigue during your period.",
      bloating: "Cutting back on salty foods and sipping water through the day may ease bloating.",
      nausea: "Small, light meals and ginger tea can sometimes help settle nausea.",
      backpain: "A warm compress on your lower back and gentle stretching may bring relief.",
    };
    high.forEach(s => {
      tips.push({ emoji: "🩷", text: symptomTips[s.key] || "This symptom was rated high today — be gentle with yourself and rest where you can." });
    });
  }

  return { tips: tips.slice(0, 4), notes: notes.slice(0, 3), goods: goods.slice(0, 2) };
}

function SuggestionRow({ item, tone }) {
  const bg = tone === "tip" ? COLORS.cardAlt : tone === "good" ? "#EAF4EC" : "#FBEFD8";
  return (
    <div style={{ display: "flex", gap: 10, alignItems: "flex-start", background: bg, borderRadius: 14, padding: "11px 13px" }}>
      <span style={{ fontSize: 17, lineHeight: 1.4 }}>{item.emoji}</span>
      <span style={{ fontSize: 13, color: COLORS.plum700, lineHeight: 1.55 }}>{item.text}</span>
    </div>
  );
}

function SuggestionsCard({ data }) {
  const { tips, notes, goods } = useMemo(() => generateSuggestions(data), [data]);
  const hasProfileData = Object.values(data.profile || {}).some(Boolean) || data.lifestyleLogs.length || data.symptomLogs.length;
  if (!hasProfileData) return null;
  if (!tips.length && !notes.length && !goods.length) {
    return (
      <Card>
        <SectionLabel>✨ Personalized For You</SectionLabel>
        <div style={{ fontSize: 13.5, color: COLORS.plum500 }}>
          Log today's lifestyle data or a few symptoms and we'll surface tailored suggestions here.
        </div>
      </Card>
    );
  }
  return (
    <Card>
      <SectionLabel>✨ Personalized For You</SectionLabel>
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {tips.map((t, i) => <SuggestionRow key={`t${i}`} item={t} tone="tip" />)}
        {notes.map((t, i) => <SuggestionRow key={`n${i}`} item={t} tone="note" />)}
        {goods.map((t, i) => <SuggestionRow key={`g${i}`} item={t} tone="good" />)}
      </div>
      <div style={{ fontSize: 11, color: COLORS.plum500, marginTop: 12, lineHeight: 1.5 }}>
        Based on the lifestyle details and symptoms you've logged. General wellness suggestions only — not medical advice.
      </div>
    </Card>
  );
}

